from playwright.sync_api import sync_playwright
import base64,os
os.environ['HOME']='/tmp/dshhome'
with sync_playwright() as pw:
    b=pw.chromium.launch(executable_path='/usr/bin/google-chrome',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
    pg=b.new_page(viewport={'width':480,'height':360})
    pg.on('console',lambda m:print(m.type,m.text))
    pg.goto('http://127.0.0.1:8123/min.html')
    pg.wait_for_function('window.__ready===true',timeout=30000)
    d=pg.evaluate('window.renderAt()')
    open('min.png','wb').write(base64.b64decode(d.split(',')[1]))
    b.close()
EOF
